#include "rbtree.h"
#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>

/* Reference model: a flat array of key/value pairs, kept in sync with the
 * tree on every successful insert or delete. Linear scans are fine here —
 * this is a correctness oracle, not something that needs to be fast. */
struct model_entry {
    char *key;
    int  *value;
};

struct model {
    struct model_entry *entries;
    size_t               count;
    size_t               capacity;
};

static void model_init(struct model *m) {
    m->entries = NULL;
    m->count = 0;
    m->capacity = 0;
}

static struct model_entry *model_find(struct model *m, const char *key) {
    for (size_t i = 0; i < m->count; i++) {
        if (strcmp(m->entries[i].key, key) == 0) return &m->entries[i];
    }
    return NULL;
}

static void model_put(struct model *m, const char *key, int *value) {
    struct model_entry *e = model_find(m, key);
    if (e != NULL) {
        free(e->value);
        e->value = value;
        return;
    }
    if (m->count == m->capacity) {
