        free_count = 0;
        fault_alloc_arm(n);

        rbtree_t *t = rb_create(counting_free);
        if (t == NULL) {
            check(fault_alloc_total() == n, "[sweep] rb_create's own allocation was the n-th call");
            fault_alloc_disarm();
            continue;
